import { getCurrentPlayer, publicPlayer } from "@/lib/player-auth";
import { getPrismaClient } from "@/lib/prisma";
import { rejectCrossSiteRequest } from "@/lib/request-security";
import { isAdminEmail } from "@/lib/admin-auth";
import { canChangeAdminPhone } from "@/lib/admin-sms";

export const dynamic = "force-dynamic";

function cleanText(value: unknown, maxLength: number) {
  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
}

export async function PATCH(request: Request) {
  const crossSiteResponse = rejectCrossSiteRequest(request);
  if (crossSiteResponse) return crossSiteResponse;

  const prisma = getPrismaClient();

  if (!prisma) {
    return Response.json(
      { error: "Database is not configured." },
      { status: 500 },
    );
  }

  const currentPlayer = await getCurrentPlayer();

  if (!currentPlayer) {
    return Response.json({ error: "Login required." }, { status: 401 });
  }

  const body = (await request.json()) as {
    name?: unknown;
    phone?: unknown;
    simulatorDisplayName?: unknown;
  };
  const name = cleanText(body.name, 120);
  const phone = cleanText(body.phone, 40);
  const simulatorDisplayName = cleanText(body.simulatorDisplayName, 120);

  if (!name || !phone || !simulatorDisplayName) {
    return Response.json(
      {
        error:
          "Name, phone number, and simulator display name are required for repeat entry.",
      },
      { status: 400 },
    );
  }

  if (isAdminEmail(currentPlayer.email) && !canChangeAdminPhone(currentPlayer.phone, phone)) {
    return Response.json({ error: "This number protects your administrator login. Contact support to change your MFA phone number." }, { status: 403 });
  }

  const user = await prisma.user.update({
    data: {
      name,
      phone,
      simulatorDisplayName,
    },
    where: { id: currentPlayer.id },
    select: {
      id: true,
      name: true,
      username: true,
      email: true,
      phone: true,
      simulatorDisplayName: true,
      emailVerifiedAt: true,
    },
  });

  return Response.json({ user: publicPlayer(user) });
}

