export function isAdminSmsEnabled() {
  return process.env.PIN2WIN_ADMIN_MFA_CHANNEL === "sms";
}

export function normalizeAdminPhone(value: string | null | undefined): string | null {
  const input = value?.trim();
  if (!input || !/^[+\d().\s-]+$/.test(input)) return null;
  const compact = input.replace(/[().\s-]/g, "");
  // Pin2Win's domestic numbers use the US country code; international numbers
  // must include their explicit + country code.
  if (/^\d{10}$/.test(compact)) return `+1${compact}`;
  if (/^1\d{10}$/.test(compact)) return `+${compact}`;
  return /^\+[1-9]\d{7,14}$/.test(compact) ? compact : null;
}

export function canChangeAdminPhone(current: string | null | undefined, next: string) {
  return !isAdminSmsEnabled() || current === next ||
    (normalizeAdminPhone(current) !== null && normalizeAdminPhone(current) === normalizeAdminPhone(next));
}

async function verifyRequest(path: string, body: URLSearchParams) {
  const account = process.env.TWILIO_ACCOUNT_SID;
  const token = process.env.TWILIO_AUTH_TOKEN;
  const service = process.env.TWILIO_VERIFY_SERVICE_SID;
  if (!account || !/^AC[0-9a-f]{32}$/i.test(account) || !token ||
      !service || !/^VA[0-9a-f]{32}$/i.test(service)) {
    throw new Error("Administrator SMS provider is not configured.");
  }
  return fetch(`https://verify.twilio.com/v2/Services/${service}/${path}`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${account}:${token}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
    cache: "no-store",
    signal: AbortSignal.timeout(10_000),
  });
}

export async function startAdminSmsVerification(phone: string) {
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) throw new Error("Invalid MFA phone.");
  const response = await verifyRequest("Verifications", new URLSearchParams({
    To: phone, Channel: "sms",
  }));
  if (!response.ok) throw new Error("Administrator verification text could not be sent.");
  const data = await response.json() as { sid?: string; status?: string };
  if (!data.sid || !/^VE[0-9a-f]{32}$/i.test(data.sid) || data.status !== "pending") {
    throw new Error("Administrator verification text was not accepted.");
  }
  return data.sid;
}

export async function checkAdminSmsVerification(sid: string, code: string) {
  if (!/^VE[0-9a-f]{32}$/i.test(sid) || !/^\d{6}$/.test(code)) return false;
  const response = await verifyRequest("VerificationCheck", new URLSearchParams({
    VerificationSid: sid, Code: code,
  }));
  // Twilio removes expired, consumed, and attempt-exhausted verifications.
  if (response.status === 404 || response.status === 429) return false;
  if (!response.ok) throw new Error("Administrator text verification is unavailable.");
  const data = await response.json() as { sid?: string; status?: string };
  return data.sid === sid && data.status === "approved";
}

