import test, { afterEach, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeAdminPhone, canChangeAdminPhone, startAdminSmsVerification, checkAdminSmsVerification } from './admin-sms.ts';

const keys = ['PIN2WIN_ADMIN_MFA_CHANNEL', 'TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_VERIFY_SERVICE_SID'];
const original = Object.fromEntries(keys.map(key => [key, process.env[key]]));
const originalFetch = globalThis.fetch;
const sid = `VE${'a'.repeat(32)}`;
beforeEach(() => {
  process.env.PIN2WIN_ADMIN_MFA_CHANNEL = 'sms';
  process.env.TWILIO_ACCOUNT_SID = `AC${'a'.repeat(32)}`;
  process.env.TWILIO_AUTH_TOKEN = 'test-only';
  process.env.TWILIO_VERIFY_SERVICE_SID = `VA${'b'.repeat(32)}`;
});
afterEach(() => {
  globalThis.fetch = originalFetch;
  for (const key of keys) {
    if (original[key] === undefined) delete process.env[key];
    else process.env[key] = original[key];
  }
});

test('normalizes account phone formats and rejects extensions and malformed numbers', () => {
  assert.equal(normalizeAdminPhone('(210) 555-0123'), '+12105550123');
  assert.equal(normalizeAdminPhone('1-210-555-0123'), '+12105550123');
  assert.equal(normalizeAdminPhone('+44 7700 900123'), '+447700900123');
  for (const value of [null, '', '555', '++12105550123', '2105550123 ext 9', '+0123456789']) {
    assert.equal(normalizeAdminPhone(value), null);
  }
});

test('SMS admin profile cannot replace the second factor, but formatting changes work', () => {
  assert.equal(canChangeAdminPhone('2105550123', '(210) 555-0123'), true);
  assert.equal(canChangeAdminPhone('2105550123', '2105550124'), false);
  assert.equal(canChangeAdminPhone(null, '2105550124'), false);
  process.env.PIN2WIN_ADMIN_MFA_CHANNEL = 'email';
  assert.equal(canChangeAdminPhone('2105550123', '2105550124'), true);
});

test('sends only to the account destination using Twilio SMS', async () => {
  globalThis.fetch = async (url, options) => {
    assert.match(url, /\/Verifications$/);
    assert.equal(options.body.get('To'), '+12105550123');
    assert.equal(options.body.get('Channel'), 'sms');
    assert.equal(options.body.has('CustomCode'), false);
    return Response.json({ sid, status: 'pending' });
  };
  assert.equal(await startAdminSmsVerification('+12105550123'), sid);
});

test('provider failures and missing credentials fail closed', async () => {
  globalThis.fetch = async () => new Response('', { status: 500 });
  await assert.rejects(startAdminSmsVerification('+12105550123'));
  await assert.rejects(checkAdminSmsVerification(sid, '123456'));
  delete process.env.TWILIO_AUTH_TOKEN;
  globalThis.fetch = async () => assert.fail('must not send without credentials');
  await assert.rejects(startAdminSmsVerification('+12105550123'));
});

test('checks the server-stored verification ID and requires matching approval', async () => {
  globalThis.fetch = async (url, options) => {
    assert.match(url, /\/VerificationCheck$/);
    assert.equal(options.body.get('VerificationSid'), sid);
    assert.equal(options.body.get('Code'), '123456');
    assert.equal(options.body.has('To'), false);
    return Response.json({ sid, status: 'approved' });
  };
  assert.equal(await checkAdminSmsVerification(sid, '123456'), true);
  for (const body of [{ sid, status: 'pending' }, { sid: `VE${'c'.repeat(32)}`, status: 'approved' }]) {
    globalThis.fetch = async () => Response.json(body);
    assert.equal(await checkAdminSmsVerification(sid, '123456'), false);
  }
  for (const status of [404, 429]) {
    globalThis.fetch = async () => new Response('', { status });
    assert.equal(await checkAdminSmsVerification(sid, '123456'), false);
  }
});

test('malformed codes and verification IDs never contact provider', async () => {
  globalThis.fetch = async () => assert.fail('invalid verification input');
  assert.equal(await checkAdminSmsVerification(sid, '12345'), false);
  assert.equal(await checkAdminSmsVerification('../other', '123456'), false);
});
